def transform(g):
    h,w=len(g),len(g[0])
    def bands(sep,n):
        b=[];s=0
        for x in sep: b.append((s,x-1)); s=x+1
        b.append((s,n-1)); return b
    rsep=[r for r in range(h) if all(g[r][c]==8 for c in range(w))]
    csep=[c for c in range(w) if all(g[r][c]==8 for r in range(h))]
    rb=bands(rsep,h); cb=bands(csep,w)
    nb,nb2=len(rb),len(cb)
    seeds2=[];seeds3=[]
    for i,(r0,r1) in enumerate(rb):
        for j,(c0,c1) in enumerate(cb):
            blk=[g[r][c] for r in range(r0,r1+1) for c in range(c0,c1+1)]
            if 2 in blk: seeds2.append((i,j))
            if 3 in blk: seeds3.append((i,j))
    paint2=set(); paint3=set()  # (rb_idx, cb_idx) painted by each color
    # color 2: vertical main axis
    for j in {b for a,b in seeds2}:
        rows=sorted(a for a,b in seeds2 if b==j)
        span=set(range(rows[0],rows[-1]+1)) if len(rows)>1 else set(range(nb))
        paint2|={(i,j) for i in span}
    for i in {a for a,b in seeds2}:
        cols=sorted(b for a,b in seeds2 if a==i)
        if len(cols)>1: paint2|={(i,j) for j in range(cols[0],cols[-1]+1)}
    # color 3: horizontal main axis
    for i in {a for a,b in seeds3}:
        cols=sorted(b for a,b in seeds3 if a==i)
        span=set(range(cols[0],cols[-1]+1)) if len(cols)>1 else set(range(nb2))
        paint3|={(i,j) for j in span}
    for j in {b for a,b in seeds3}:
        rows=sorted(a for a,b in seeds3 if b==j)
        if len(rows)>1: paint3|={(i,j) for i in range(rows[0],rows[-1]+1)}
    out=[row[:] for row in g]
    for i,(r0,r1) in enumerate(rb):
        for j,(c0,c1) in enumerate(cb):
            hh=(r1-r0+1,c1-c0+1)
            if hh!=(max(a[0] for a in rb),max(a[1] for a in cb)): continue  # irregular block untouched
            p2=(i,j) in paint2; p3=(i,j) in paint3
            v = 6 if p2 and p3 else 2 if p2 else 3 if p3 else 0
            for rr in range(r0,r1+1):
                for cc in range(c0,c1+1):
                    out[rr][cc]=v
    return out
